style.css:
@-moz-document domain("schoolportal.example.com") {
/* Base styles */
    body {
        background-color: #f5f5f5;
        color: #222;
        font-family: 'Segoe UI', Arial, sans-serif;
        margin: 0;
        padding: 0;
    }
    /* Heading styles */
    h1, h2, h3, h4, h5, h6 {
        color: #123e67;
        font-weight: bold;
        letter-spacing: 0.5px;
        margin-top: 1.5em;
        margin-bottom: 0.5em;
    }
    /* Links */
    a {
        color: #1da1f2;
        text-decoration: none;
        transition: color 0.2s;
    }
    a:hover {
        color: #105d82;
        text-decoration: underline;
    }
    /* Buttons */
    .button {
        background-color: #123e67;
        color: #fff;
        padding: 10px 24px;
        border: none;
        border-radius: 8px;
        font-size: 16px;
        cursor: pointer;
        transition: background 0.3s;
    }
    .button:hover {
        background-color: #305f8c;
    }
    /* Custom container */
    .container {
        max-width: 1200px;
        margin: 0 auto;
        padding: 30px;
        background: #fff;
        border-radius: 10px;
        box-shadow: 0 4px 40px rgba(0,0,0,0.07);
    }
    /* Form elements */
    input[type="text"], textarea {
        border: 1px solid #ccc;
        border-radius: 6px;
        background: #fafafa;
        padding: 8px 10px;
        font-size: 15px;
        width: 100%;
        margin-bottom: 12px;
        box-sizing: border-box;
    }
    input:focus, textarea:focus {
        border-color: #123e67;
        outline: none;
    }
}
